INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('32556908-8127-4713-ab62-f080d0422071', 'naturales', '4to', '{"id":"32556908-8127-4713-ab62-f080d0422071","name":"Ciencias de la vida ","themes":[{"id":"0157729b-979d-4d40-b050-0f3e4056dfa9","name":"Materia y sus propiedades","subthemes":[{"id":"22ede522-b714-4bcd-8568-477b84bc2aa4","name":"Qué es la materia y dónde la encontramos."},{"id":"ef46d249-3512-428f-8421-553e1277ebf4","name":"Propiedades de la materia (forma, tamaño, color, estado)."},{"id":"0b771a80-d481-4280-961b-7d0e973ed3ad","name":"Cambios simples en la materia."}]},{"id":"2b739b78-04eb-4442-a503-0dd6a011da65","name":"La biodiversidad de los seres vivos y su organización celular","subthemes":[{"id":"5c640ee8-e654-488c-b331-22dde132c566","name":"La célula como unidad básica de los seres vivos."},{"id":"1f399709-cedc-4a8f-b892-d829e5a07dd4","name":"Diversidad de seres vivos en el planeta."},{"id":"56360a8a-d11f-4315-9db4-938ee070df12","name":"Importancia de la biodiversidad para la vida."}]},{"id":"f1151be2-8128-4dec-8963-9f9566582ac9","name":"Las plantas: endémicas y nativas","subthemes":[{"id":"a60b788a-3526-4c7d-bf26-b5f83b1e4de9","name":"Qué son plantas endémicas y nativas."},{"id":"a0c423ac-6b80-4cfd-a131-a67f83c88b21","name":"Ejemplos de plantas endémicas y nativas de Rep. Dom."},{"id":"bb7c8011-264b-485d-807e-853b189565ac","name":"Importancia de las plantas para el ambiente y la vida."}]},{"id":"ed924ac2-2160-4922-b27c-2e4a0c8b8a93","name":"Los animales: endémicos y nativos","subthemes":[{"id":"456420ae-5c78-4859-a3d2-f142191cf992","name":"Importancia de la fauna para el equilibrio natural."},{"id":"7edd33fd-6ee5-41e9-8e80-06a72b8d8e4b","name":"Qué son animales endémicos y nativos."},{"id":"ef5351c4-ffc9-463a-94ba-cd814af0fa5b","name":"Ejemplos de animales endémicos y nativos del país."}]},{"id":"83a2a2c4-6585-479d-aaa0-27a79a57f4d8","name":"Reproducción: asexual y sexual","subthemes":[{"id":"b9763b42-0685-43b0-beed-70aaf4d28342","name":"Reproducción sexual en los seres vivos."},{"id":"23759a98-ae8e-4551-8a78-190d9bb49039","name":"Importancia de la reproducción para la continuidad de la vida."},{"id":"7023c275-e6f0-40b5-b17d-890045aa5a7c","name":"Reproducción asexual en plantas y animales."}]},{"id":"0f6920d3-db00-43b2-9bf4-ed7b6df6b213","name":"Caracteres hereditarios","subthemes":[{"id":"1411a1ae-dc90-490c-9641-25eaf8bf7918","name":"Qué son los caracteres hereditarios."},{"id":"06fe451d-7cdf-44ef-bf05-d758acf84ad5","name":"Características que se heredan de padres a hijos."},{"id":"a8f65795-3ffb-4456-9742-6f204cab3ba0","name":"Importancia de la herencia en los seres vivos."}]},{"id":"38265599-c146-44e0-a058-0d40e3f8d4d1","name":"Energía y conservación","subthemes":[{"id":"a1b8a6c9-c0a9-434b-8ce7-faa657b9f813","name":"Nutrición en plantas y animales"},{"id":"e479040c-6c6b-4f83-a56f-1a7fe9542b1a","name":"La fotosíntesis"},{"id":"0942a418-5357-4d2c-956e-442f3191e7a4","name":"Flujo de energía en ecosistemas."}]},{"id":"d0b1283c-6694-41da-aeb1-fff7b418409d","name":"Interacción y movimiento","subthemes":[{"id":"7becbeb5-dfe9-4e99-8ca1-936e9c717717","name":"Movimiento en planta"}]},{"id":"67a579c7-e714-4ac1-9318-b888a02beb7c","name":"Sistema y mecanismo","subthemes":[{"id":"7c2963f3-e080-448a-a33b-ff49b7fd71be","name":"Los ecosistemas"},{"id":"ea597f42-f60f-43e8-b78c-3308404aa5dc","name":"Los recursos naturales"},{"id":"08af1a32-3603-4336-a7e2-7029f25ca804","name":"La agricultura: cultivos y huertos escolares"}]},{"id":"f0cea955-ec1b-4674-89ea-afed5361d138","name":"Salud y ser humano","subthemes":[{"id":"e02030e1-91f6-4b2a-ace4-5e7007939b45","name":"Desarrollo y cambio en el ser humano"},{"id":"f77bdb90-ee4e-493c-a623-aabc9ea3d12b","name":"Cuidado del cuerpo humano"},{"id":"48daa4d6-a398-4cf1-b51a-b07464728753","name":"Enfermedades tropicales y virales (transmitidas por vectores)"}]}],"grade_levels":["4to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"32556908-8127-4713-ab62-f080d0422071-block-1","themes":["Materia y sus propiedades","La biodiversidad de los seres vivos y su organización celular","Las plantas: endémicas y nativas","Los animales: endémicos y nativos","Reproducción: asexual y sexual","Caracteres hereditarios","Energía y conservación","Interacción y movimiento","Sistema y mecanismo","Salud y ser humano"],"conceptual":"Ciencias de la Vida \nMateria y sus propiedades\n–\tLa biodiversidad de los seres vivos y su organización celular.\n–\tLas plantas: endémicas y nativas.\n–\tLos animales: endémicos y nativos.\n–\tReproducción: asexual y sexual.\n–\tCaracteres hereditarios.\nEnergía y conservación\n–\tNutrición en plantas y animales.\n–\tLa fotosíntesis.\n–\tFlujo de energía en ecosistemas.\nInteracción y movimiento – Movimiento en plantas.\nSistema y mecanismo\n–\tLos ecosistemas y los recursos naturales.\n–\tLa agricultura: cultivos y huertos escolares.\nSalud y ser humano\n–\tDesarrollo y cambio en el ser humano.\n–\tCuidado del cuerpo humano.\n–\tEnfermedades tropicales y virales (transmitidas por vectores).\n ","procedural":"Ciencias de la Vida\n–\tDescripción e interpretación de las células vegetal y animal. \nProcedimiento: uso de modelos, material audiovisual (video educativo, película, documental, atlas, lámina), utilización de instrumentos (microscopio, estereoscopio), observación, dibujos, comparación, conclusión, exposición de resultados.\n–\tIndagación: seres vivos unicelulares y multicelulares. Procedimiento: formulación de preguntas, búsqueda de información, planteamiento de hipótesis, experimentación, interpretación, selección de la información, comparación, inferencia, argumentación, dibujos, reporte en diario de laboratorio.\n–\tObservación de las partes de las plantas: raíz, tallo, hoja, flor, fruto, semilla. Procedimiento: exploración de plantas de su entorno y construcción de modelos.\n–\tObservación de raíces, hojas y flores de su entorno. Procedimiento: utilización de recursos del medio, materiales didácticos y audiovisuales, recolección de información, comparación, clasificación, descripción, dibujos, comunicación de los resultados y reporte diario de laboratorio.\n–\tExploración del cuerpo de los animales de su entorno. Procedimiento: uso de material didáctico (atlas, láminas), instrumentos (microscopio, estereoscopio), audiovisuales (videos, películas, documentales), construcción de modelos, comparación, clasificación, descripción, comunicación oral y escrita, dibujos.\n–\tCaracterización del cuerpo, órganos y sistemas de la especie humana (digestivo, circulatorio, respiratorio, excretor, nervioso y reproductor). Procedimiento: uso de material didáctico (láminas, atlas, modelos), audiovisual (videos, películas, documentales) y aparatos (microscopio, estereoscopio), construcción de modelos, comparación, clasificación, descripción, inferencia, comunicación oral y escrita, dibujos.\n \n–\tIndagación sobre los cambios biológicos que ocurren durante la pubertad. Procedimiento: exploración, utilización de material didáctico (láminas, libros, atlas), audiovisuales (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tIndagación sobre la reproducción sexual y asexual en los seres vivos. Procedimiento: formulación de preguntas, búsqueda de información, utilización de material didáctico (láminas, libros, atlas) y audiovisual (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tIndagación sobre la reproducción sexual y asexual en los seres vivos. Procedimiento: formulación de preguntas, búsqueda de información, utilización de material didáctico (láminas, libros, atlas) y audiovisual (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tExperimentación (guiada) sobre el proceso de fotosíntesis en las plantas. Procedimiento: recolección de información, formulación de preguntas, planteamiento de hipótesis, experimentación, registro de información, comparación, inferencia, argumentación, discusión, comunicación de resultados, redacción y exposición.\n–\tExploración de componentes del entorno: bióticos y abióticos, y su interacción en el entorno. Procedimiento: \nobservación, preguntas, planteamiento de hipótesis, búsqueda de información, descripción, medición, tabulación, comparación, inferencia, argumentación, contrastación de las hipótesis, discusión, conclusión, exposición.\n–\tIndagación sobre los recursos naturales de la isla de Santo Domingo. Procedimiento: observación, interpretación de mapas temáticos, recolección de información, clasificación, comparación, construcción de modelos, dibujos, comunicación oral y escrita.\n–\tIndagación sobre la biodiversidad autóctona, flora y fauna (nativa y endémica), de la isla de Santo Domingo. Procedimientos: observación, recolección de información, construcción de modelos, clasificación, descripción, elaboración e interpretación de mapas temáticos, interpretación, comentarios, exposición.\n–\tIndagación sobre las enfermedades de las plantas y animales que habitan en su entorno inmediato o localidad. Procedimiento: preguntas de investigación, planificación, búsqueda de información, diseño, planteamiento de hipótesis, entrevistas, experimentación, toma de datos, interpretación, selección de información, inferencia, redacción y exposición.\n ","attitudinal":"–\tMotivación e interés en el uso sostenible de los recursos, asumiendo una actitud de ahorro e integrándose al reúso, reducción y reciclaje de materiales.\n–\tValoración y protección de la biodiversidad, así como de los entornos local, regional y global.\n–\tManifestación de cooperación e interés ante la situación de salubridad de su entorno, contribuyendo al mantenimiento de un espacio adecuado para una vida de calidad.\n–\tDemostración de interés por aprender sobre el funcionamiento y la salud de los sistemas del cuerpo humano.\n–\tParticipación en los proyectos, en la toma de decisiones y en la búsqueda de soluciones a situaciones problemáticas.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T21:56:00.000Z');

INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('478b0a16-3c48-40a8-87fa-f6343d784ab9', 'naturales', '4to', '{"id":"478b0a16-3c48-40a8-87fa-f6343d784ab9","name":"Ciencias físicas","themes":[{"id":"cbe528a0-4922-43e4-9fdc-510219ffa4c7","name":"Materia y sus propiedades ","subthemes":[{"id":"59bdcdda-436b-47ae-833b-a89d2bafcc35","name":"La luz"},{"id":"d9d453bb-1ece-4049-82eb-0e8eb11edfff","name":"Los colores"},{"id":"e6d9a4bb-5f33-48c5-a69d-b6798d66424c","name":"Reflexión, refracción y difracción"},{"id":"39f6ea36-9a44-4697-8c5c-22f8785720fd","name":"Sustancias, combinaciones y mezclas (homogéneas y heterogéneas)."}]},{"id":"43d51cf0-a0e3-41bb-a825-8ddf3d7a327f","name":"Energía y conservación","subthemes":[{"id":"4d620a9a-a2dd-455a-a7df-4b70ee9d75de","name":"Energía química"},{"id":"3c8cd789-2517-44b6-98a2-d5452756dc6a","name":"Energía"},{"id":"fef950f7-ed3a-4fed-99e8-8babd170d96f","name":"Transformación"},{"id":"5b4d1dcb-eedd-44bd-8fc0-f12a239b9dd6","name":"Transmisión "},{"id":"af65e5b7-cc44-4aab-8fbb-c6dcd518fb62","name":"Energía solar"}]},{"id":"6fb1ba42-8cb8-4873-b8ac-103078ea072c","name":"Interacción y movimiento","subthemes":[{"id":"9373b1a2-a693-4d42-a492-5e701166459d","name":"Movimiento en línea recta  (luz). "},{"id":"9b2f03a9-ff05-44be-bde5-90d5d4396316","name":"Interacción de la luz con líquido y sólido."}]},{"id":"caf8bb7a-97be-4c29-8a9f-c123555e8d3a","name":"Sistema y mecanismo","subthemes":[{"id":"e2690819-3a75-4d03-9d82-51168296a6f7","name":"Prismas, espejos y lentes. "},{"id":"4705ce50-74e4-44bc-9b25-8e206f2febae","name":"Instrumentos ópticos."},{"id":"1775ad44-ce83-401e-a906-3cb3229f1171","name":"Mecanismos de transmisión de movimiento (palancas, poleas simples y distintas ruedas, tornillos sin fin)"},{"id":"90949e9a-e9ad-4f31-9fc9-43418c45295e","name":"Tecnología en la medicina"},{"id":"2f18fe34-859a-4d30-8b92-511de57ed12d","name":"Placa de rayos X, sonografía, análisis médicos e instrumentos ópticos."}]},{"id":"4ad32745-1141-4309-ac5a-80c332f17692","name":"El Poder de las Ondas: Aplicaciones y Descubrimientos","subthemes":[]}],"grade_levels":["4to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"478b0a16-3c48-40a8-87fa-f6343d784ab9-block-1","themes":["Materia y sus propiedades ","Energía y conservación","Interacción y movimiento","Sistema y mecanismo","El Poder de las Ondas: Aplicaciones y Descubrimientos"],"conceptual":"\"Ciencias físicas\"\nMateria y sus propiedades – La luz.\n–\tLos colores.\n–\tReflexión, refracción y difracción.\n–\tSustancias, combinaciones y mezclas (homogéneas y heterogéneas).\nEnergía y conservación\n–\tEnergía, transmisión y transformación: solar y química. \nInteracción y movimiento\n–\tInteracción de la luz con líquido y sólido.\n–\tMovimiento en línea recta \n(luz). \nSistema y mecanismo\n–\tPrismas, espejos y lentes. Instrumentos ópticos.\n–\tMecanismos de transmisión de movimiento (palancas, poleas simples y distintas ruedas, tornillos sin fin).\n–\tTecnología en la medicina (placa de rayos X, sonografía, análisis médicos e instrumentos ópticos).\n ","procedural":"Ciencias físicas\n–\tClasificación de materiales transparentes, opacos y traslúcidos. Procedimiento: exploración, comparación, clasificación, descripción, conclusión de hallazgos.\n–\tExperimentación de la refracción de la luz en líquidos. Procedimiento: observación, utilización de instrumentos, medición, descripción, inferencia, dibujos y registro de información en diario de laboratorio.\n–\tObservación de la difracción de la luz a través de una o dos rendijas. Procedimiento: Exploración, construcción de modelos, descripción, esquemas o gráficos, comunicación en forma oral y escrita.\n–\tExploración sobre el comportamiento de la luz a través de distintas sustancias. Procedimiento: utilización de instrumentos, recolección y registro de informaciones, análisis y discusión.\n–\tExperimentación sobre la reflexión de la luz: ángulo de incidencia y ángulo de reflexión. Procedimiento: observación, uso de instrumentos, recolección de información, comparación, dibujo de esquema y registros en diario de laboratorio.\n–\tExperimentación sobre la descomposición de la luz blanca con un prisma. Procedimiento: exploración, utilización de instrumentos, descripción, comunicación de resultados mediante el uso de esquemas y dibujos a colores.\n–\tDescripción de la transmisión de energía (radiación de la luz). Procedimiento: formulación de preguntas, recolección de información, utilización de instrumentos, planificación de experimentos, puesta en común de resultados.\n–\tExperimentación sobre la transformación de la energía: solar y química. Procedimiento: observación, utilización de instrumentos, construcción de modelos, comparación, descripción, esquemas, gráficos y diario de laboratorio.\n–\tObservación de cámara oscura, caleidoscopio, microscopio sencillo. Procedimiento: exploración, formulación de preguntas, construcción de modelos, planificación de experimentos, presentación de resultados.\n–\tIndagación a partir de la observación y comparación entre sustancias, combinaciones y mezclas.\n–\tExperimentación(guiada) con distintos materiales que constituyen las mezclas homogéneas y heterogéneas. Procedimiento: recolección de información, utilización de materiales de uso cotidiano, planificación de experimentos, comparación, clasificación, comunicación oral y escrita, registro de información en el diario de laboratorio.\n–\tExperimentación (guiada) sobre técnicas de separación de mezclas. Procedimiento: exploración, formulación de preguntas, recolección de información, descripción, utilización o construcción de instrumentos y equipos sencillos, registro de información, comunicación escrita.\n–\tDiseño y elaboración equipos utilizando materiales reciclables para la realización de las separaciones de mezclas. Procedimiento: planificación, diseño, recolección de materiales, elaboración de equipos, experimentación.\n ","attitudinal":"–\tManifestación de curiosidad, creatividad, objetividad.\n–\tComunicación de sus ideas, seguimiento de procedimiento, trabajo individual y colaborativo. Respeto a las ideas y diferencias de las demás personas, solidaridad. Utilización sostenible de los recursos tecnológicos de que dispone.\n–\tDemostración de interés por conocer las propiedades y características de la luz y la materia; por utilizar herramientas, construir máquinas y modelar estructuras e instrumentos, así como por la preparación y separación de mezclas.\n–\tMotivación por aprender cosas nuevas de su entorno material y tecnológico.\n–\tAdopción de medidas de cuidado, protección y prevención con respecto a la luz, sustancias y mezclas que puedan afectar sus órganos o su salud.\n–\tEvaluación y prevención de los riesgos de la interacción de la radiación con la materia. Asume la importancia de las informaciones médicas acerca de su salud.\n–\tValoración de los aportes y avances científicos y tecnológicos en los aparatos electrónicos médicos y su impacto en la sociedad y el Medioambiente.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T21:56:00.000Z');

INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('a381f5fc-38bf-4bb1-9235-9bc53ab48d00', 'naturales', '4to', '{"id":"a381f5fc-38bf-4bb1-9235-9bc53ab48d00","name":"Ciencias de la tierra y el universo ","themes":[{"id":"0edbb88d-7847-4db4-a6cc-1289d1ab543c","name":"Materia y sus propiedades","subthemes":[{"id":"156c8ae3-8804-419a-82ee-da83599ad2c9","name":"Composición física del planeta Tierra"},{"id":"d9ae73b5-8fd9-47ed-bf38-24b387ce772b","name":"Fenómenos naturales. Sismos."}]},{"id":"e7f6bbfb-3e8d-4d07-87b5-95b7859ddf19","name":"Energía y conservación ","subthemes":[{"id":"f7813f8f-fe4f-4323-88ff-35e2bce21f42","name":"El Sol: fuente de energía."},{"id":"934e41c0-60d2-4e95-a679-cad99db81bfd","name":"Eficiencia energética."}]},{"id":"c51cc27e-a330-4bb5-ac9b-91ad9f2be251","name":"Sistema y mecanismo","subthemes":[{"id":"f369b322-a238-4278-9b82-cda942dde35a","name":"–\\tSistema Solar: Sol, planetas, satélites, luna, cometas."}]},{"id":"12717e60-62ec-4f38-8759-ef1f2e0a0987","name":"Interacción y movimiento","subthemes":[{"id":"555d6138-ffd2-455e-8d43-d1f7b07fb2bb","name":"Eclipse."},{"id":"851276f8-b11c-4184-9802-77a2da8f8b8b","name":"Movimiento y trayectoria de los planetas del Sistema Solar."}]}],"grade_levels":["4to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"a381f5fc-38bf-4bb1-9235-9bc53ab48d00-block-1","themes":["Materia y sus propiedades","Energía y conservación ","Sistema y mecanismo","Interacción y movimiento"],"conceptual":"\"Ciencias de la tierra y el universo\"\n \nMateria y sus propiedades\n–\tComposición física del planeta Tierra.\n–\tFenómenos naturales. Sismos.\nEnergía y conservación \n–\tEl Sol: fuente de energía.\n–\tEficiencia energética.\nSistema y mecanismo\n–\tSistema Solar: Sol, planetas, satélites, luna, cometas.\nInteracción y movimiento\n–\tMovimiento y trayectoria de los planetas del Sistema Solar.\n–\tEclipse.\n ","procedural":"\"Ciencias de la tierra y el universo\"\n \n–\tDescripción y comparación entre el manto y la corteza del planeta Tierra. Comunicación por medio de dibujos y esquemas.\n–\tObservación, descripción y comparación entre rocas y minerales, clasificándolos de acuerdo a sus propiedades y características físicas.\n–\tAnálisis y discusión sobre sismos y energía, reconociendo que los sismos liberan grandes cantidades de energía capaces de hacer daño a estructuras y seres vivos.\n–\tExperimentación guiada sobre el Sol como fuente de energía. Análisis a través de fuentes tecnológicas diferentes, y comunicación de resultados.\n–\tObservación, descripción y comparación entre la Luna, el Sol, planetas, estrellas y cometas. Comunicación por medio de dibujos y esquemas.\n–\tAnálisis y discusión (comparación, clasificación, descripción) sobre los planetas, la Luna y otros cuerpos del Sistema Solar, y sus movimientos y trayectorias alrededor del Sol. Comunicación por medio de dibujos, esquemas, observación de videos.\n–\tDescripción y experimentación guiada sobre los eclipses, comunicando sus observaciones por medio de dibujos, o por el análisis de lecturas y noticias.\n ","attitudinal":"–\tMotivación e interés por aprender sobre sí mismo, sobre su entorno y por mantener una convivencia sana, mostrando solidaridad, respeto y colaboración con los demás.\n–\tAdopción de medidas de cuidado y utilización sostenible de los recursos naturales.\n–\tDemostración de interés por seguir instrucciones de seguridad y cuidado ante la manifestación de riesgos asociados a fenómenos naturales (sismos)\n–\tValoración de la Luna y el Sol y los beneficios para la vida en el planeta Tierra.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T21:56:00.000Z');
